%[text] # **Strongly nonlinear dynamic demonstration of adaptiveAnalyze**
%[text] The example separates convergence recovery from time-integration accuracy. A fine solution provides the reference, while ordinary and adaptive analyses use the same coarse outer time step.
%[text] The same nonlinear oscillator is solved three ways:
%[text]   1\. Fine reference:      Newton, dt = 0.001 s
%[text]   2\. Ordinary coarse:     Newton, dt = 0.020 s
%[text]   3\. Adaptive coarse:     ModifiedNewton, dt = 0.020 s
%[text] The adaptive and ordinary coarse analyses should closely agree because they use the same outer time step. Both may differ from the fine reference because convergence recovery does not control time-integration accuracy.
%[text] adaptiveAnalyze always completes the current outer target before starting the next one. If a 0.02 s step is subdivided, the accepted substeps must still add up to exactly 0.02 s.
%[text] ![](text:image:1a22)
clear;
clc;
close all;

opsMAT = OpenSeesMatlab;
ops = opsMAT.opensees;
%%
%[text] ### Parameters
p.mass = 1.0;
p.Fy = 5.0;
p.E0 = 100.0;
p.b = 0.01;
p.R0 = 18.0;
p.cR1 = 0.925;
p.cR2 = 0.15;
p.massDamping = 0.02;

p.forceAmplitude = 12.0;
p.forcePeriod = 0.5;
p.duration = 5.0;

referenceDt = 0.001;
coarseDt = 0.020;

adaptiveResponseFile = string(tempname) + '_adaptive_response.txt';
adaptiveLogFile = string(tempname) + '_adaptive_log.csv';

cleanupFiles = onCleanup(@() deleteFiles( ...
    adaptiveResponseFile, adaptiveLogFile)); %#ok<NASGU>

%%
%[text] ### Fine-step Newton reference
fprintf('\nRunning the fine-step Newton reference analysis...\n'); %[output:5f7faa9a]
[referenceTime, referenceDisp] = runFixedAnalysis( ...
    ops, p, referenceDt, 'Newton', 1.0e-12, 30);

%%
%[text] ### Ordinary coarse-step Newton analysis
fprintf('Running the ordinary coarse-step Newton analysis...\n'); %[output:16b68ef9]

[ordinaryTime, ordinaryDisp] = runFixedAnalysis( ...
    ops, p, coarseDt, 'Newton', 1.0e-12, 30);

%%
%[text] ### Adaptive coarse-step analysis
fprintf('Running the adaptive coarse-step analysis...\n'); %[output:8802099c]

buildModel(ops, p);
configureAnalysis(ops, 'ModifiedNewton', 1.0e-8, 3);

% Record every accepted adaptive step. Accepted internal substeps also
% appear here if a failed outer step must be subdivided.
ops.recorder( ...
    'Node', ...
    '-file', adaptiveResponseFile, ...
    '-precision', 16, ...
    '-time', ...
    '-node', 2, ...
    '-dof', 1, ...
    'disp');

coarseSteps = round(p.duration / coarseDt);

adaptiveCode = ops.adaptiveAnalyze( ... %[output:group:6be770a0] %[output:03953d23]
    coarseSteps, coarseDt, ... %[output:03953d23]
    '-algorithms', 'KrylovNewton', 'Newton', ... %[output:03953d23]
    '-subdivision', 0.5, 1.0e-5, 10, ... %[output:03953d23]
    '-limits', 1000, ... %[output:03953d23]
    '-log', adaptiveLogFile); %[output:group:6be770a0] %[output:03953d23]

if adaptiveCode ~= 0
    error('Adaptive analysis failed at t = %.8f with code %d.', ...
        ops.getTime(), adaptiveCode);
end

% Close the recorder before reading its file.
ops.remove('recorders');

adaptiveData = readmatrix(adaptiveResponseFile);

if isempty(adaptiveData) || size(adaptiveData, 2) < 2
    error('The adaptive displacement recorder produced invalid data.');
end

% The recorder starts after the first accepted step, so add the initial
% zero state explicitly.
adaptiveTime = [0.0; adaptiveData(:, 1)];
adaptiveDisp = [0.0; adaptiveData(:, 2)];

%%
%[text] ### Recovery statistics
attemptLog = readtable(adaptiveLogFile);

% Recovery-stage identifiers:
%   0 = original configuration
%   1 = increased iteration limit
%   2 = fallback algorithm
%   3 = subdivision event
%   4 = fallback convergence test
originalAttempts = nnz(attemptLog.stageID == 0);
algorithmAttempts = nnz(attemptLog.stageID == 2);
algorithmSuccesses = nnz( ...
    attemptLog.stageID == 2 & attemptLog.successFlag == 1);
subdivisions = nnz(attemptLog.stageID == 3);

fprintf('\nAdaptive recovery summary\n'); %[output:3c67dfd5]
fprintf('  Original attempts:           %d\n', originalAttempts); %[output:8327b935]
fprintf('  Fallback algorithm attempts: %d\n', algorithmAttempts); %[output:50617146]
fprintf('  Fallback algorithm successes:%d\n', algorithmSuccesses); %[output:82e85832]
fprintf('  Subdivision events:          %d\n', subdivisions); %[output:5bdad65d]
%%
%[text] ### Compare results at identical physical times
% The adaptive output may contain internal substep times. Interpolate both
% comparison solutions at exactly those times.
referenceAtAdaptive = interp1( ...
    referenceTime, referenceDisp, adaptiveTime, 'linear');

ordinaryAtAdaptive = interp1( ...
    ordinaryTime, ordinaryDisp, adaptiveTime, 'linear');

adaptiveReferenceError = adaptiveDisp - referenceAtAdaptive;
ordinaryReferenceError = ordinaryAtAdaptive - referenceAtAdaptive;
adaptiveOrdinaryError = adaptiveDisp - ordinaryAtAdaptive;

maxAdaptiveReferenceError = max(abs(adaptiveReferenceError));
maxOrdinaryReferenceError = max(abs(ordinaryReferenceError));
maxAdaptiveOrdinaryError = max(abs(adaptiveOrdinaryError));

rmsAdaptiveReferenceError = ...
    sqrt(mean(adaptiveReferenceError.^2));

rmsAdaptiveOrdinaryError = ...
    sqrt(mean(adaptiveOrdinaryError.^2));

referencePeak = max(abs(referenceDisp));
ordinaryPeak = max(abs(ordinaryDisp));
adaptivePeak = max(abs(adaptiveDisp));

%%
%[text] ### Stored regression values
% These values were obtained using Newton, Newmark average acceleration,
% dt = 0.001 s, tolerance = 1e-12, and 30 maximum iterations.
expectedReferencePeak = 0.245473151640312;
expectedReferenceFinal = 0.064566975576412;

fprintf('\nResponse comparison\n'); %[output:3efbd120]
fprintf('  Reference peak displacement:      %.12f\n', referencePeak); %[output:43d89073]
fprintf('  Ordinary coarse peak displacement:%.12f\n', ordinaryPeak); %[output:3bd22733]
fprintf('  Adaptive peak displacement:       %.12f\n', adaptivePeak); %[output:122396b9]
fprintf('  Reference final displacement:     %.12f\n', referenceDisp(end)); %[output:9b5e198d]
fprintf('  Ordinary final displacement:      %.12f\n', ordinaryDisp(end)); %[output:49f22a9d]
fprintf('  Adaptive final displacement:      %.12f\n', adaptiveDisp(end)); %[output:65e99d3a]

fprintf('\nError comparison\n'); %[output:7a653845]
fprintf('  Adaptive versus reference, max:   %.6e\n', ... %[output:group:90cbc189] %[output:2450a8c0]
    maxAdaptiveReferenceError); %[output:group:90cbc189] %[output:2450a8c0]
fprintf('  Ordinary versus reference, max:   %.6e\n', ... %[output:group:2845da72] %[output:5089b366]
    maxOrdinaryReferenceError); %[output:group:2845da72] %[output:5089b366]
fprintf('  Adaptive versus ordinary, max:    %.6e\n', ... %[output:group:02aca65a] %[output:6dc8227f]
    maxAdaptiveOrdinaryError); %[output:group:02aca65a] %[output:6dc8227f]
fprintf('  Adaptive versus reference, RMS:   %.6e\n', ... %[output:group:4380f3d3] %[output:5e9fbc68]
    rmsAdaptiveReferenceError); %[output:group:4380f3d3] %[output:5e9fbc68]
fprintf('  Adaptive versus ordinary, RMS:    %.6e\n', ... %[output:group:77c9b059] %[output:5e655b58]
    rmsAdaptiveOrdinaryError); %[output:group:77c9b059] %[output:5e655b58]
%%
%[text] ### Verification
% Every analysis must reach the complete requested physical time.
assert(abs(referenceTime(end) - p.duration) < 1.0e-10, ...
    'The reference analysis did not reach the final time.');

assert(abs(ordinaryTime(end) - p.duration) < 1.0e-10, ...
    'The ordinary analysis did not reach the final time.');

assert(abs(adaptiveTime(end) - p.duration) < 1.0e-10, ...
    'The adaptive analysis did not reach the final time.');

% Check the fine solution against independently stored values.
assert(abs(referencePeak - expectedReferencePeak) < 5.0e-6, ...
    'The fine-step peak does not match the stored reference.');

assert(abs(referenceDisp(end) - expectedReferenceFinal) < 5.0e-6, ...
    'The fine-step final response does not match the stored reference.');

% The important implementation check is adaptive versus ordinary coarse.
% Their common dt = 0.02 discretization should produce nearly equal results.
assert(maxAdaptiveOrdinaryError < 1.0e-5, ...
    'adaptiveAnalyze does not match ordinary analyze at the same dt.');

assert(rmsAdaptiveOrdinaryError < 1.0e-6, ...
    'The adaptive-versus-ordinary RMS error is too large.');

% Confirm that the example actually exercised algorithm switching.
assert(algorithmAttempts > 0, ...
    'No fallback algorithm was attempted.');

assert(algorithmSuccesses > 0, ...
    'No fallback algorithm converged.');
%%
%[text] ### Applied sinusoidal force
frequency = 1.0 / p.forcePeriod;

referenceForce = p.forceAmplitude * ...
    sin(2.0 * pi * frequency * referenceTime);

adaptiveForce = p.forceAmplitude * ...
    sin(2.0 * pi * frequency * adaptiveTime);
%%
%[text] ### Plots
figure( ... %[output:8dd9c4c7]
    'Color', 'white', ... %[output:8dd9c4c7]
    'Name', 'Nonlinear adaptive dynamic analysis', ... %[output:8dd9c4c7]
    'Position', [100 100 1500 800]); %[output:8dd9c4c7]

layout = tiledlayout(2, 2, ... %[output:8dd9c4c7]
    'TileSpacing', 'compact', ... %[output:8dd9c4c7]
    'Padding', 'compact'); %[output:8dd9c4c7]

title(layout, ... %[output:8dd9c4c7]
    'Nonlinear oscillator under sinusoidal loading', ... %[output:8dd9c4c7]
    'FontWeight', 'bold'); %[output:8dd9c4c7]

% Sinusoidal excitation
nexttile; %[output:8dd9c4c7]

plot(referenceTime, referenceForce, ... %[output:8dd9c4c7]
    'LineWidth', 1.5, ... %[output:8dd9c4c7]
    'Color', [0.15, 0.35, 0.75]); %[output:8dd9c4c7]

grid on; %[output:8dd9c4c7]
box on; %[output:8dd9c4c7]
xlabel('Physical time (s)'); %[output:8dd9c4c7]
ylabel('Applied force'); %[output:8dd9c4c7]
title('Input excitation'); %[output:8dd9c4c7]

% Displacement histories
nexttile; %[output:8dd9c4c7]

plot(referenceTime, referenceDisp, ... %[output:8dd9c4c7]
    '-', ... %[output:8dd9c4c7]
    'LineWidth', 2.0, ... %[output:8dd9c4c7]
    'Color', [0.10, 0.35, 0.75], ... %[output:8dd9c4c7]
    'DisplayName', 'Reference, dt = 0.001'); %[output:8dd9c4c7]

hold on; %[output:8dd9c4c7]

plot(ordinaryTime, ordinaryDisp, ... %[output:8dd9c4c7]
    '--', ... %[output:8dd9c4c7]
    'LineWidth', 1.5, ... %[output:8dd9c4c7]
    'Color', [0.10, 0.60, 0.30], ... %[output:8dd9c4c7]
    'DisplayName', 'Ordinary, dt = 0.020'); %[output:8dd9c4c7]

plot(adaptiveTime, adaptiveDisp, ... %[output:8dd9c4c7]
    '.', ... %[output:8dd9c4c7]
    'MarkerSize', 8, ... %[output:8dd9c4c7]
    'Color', [0.85, 0.20, 0.15], ... %[output:8dd9c4c7]
    'DisplayName', 'Adaptive, dt = 0.020'); %[output:8dd9c4c7]

grid on; %[output:8dd9c4c7]
box on; %[output:8dd9c4c7]
xlabel('Physical time (s)'); %[output:8dd9c4c7]
ylabel('Displacement'); %[output:8dd9c4c7]
title('Displacement response'); %[output:8dd9c4c7]
legend('Location', 'best'); %[output:8dd9c4c7]

% Coarse solutions relative to the fine reference
nexttile; %[output:8dd9c4c7]

plot(adaptiveTime, ordinaryReferenceError, ... %[output:8dd9c4c7]
    '--', ... %[output:8dd9c4c7]
    'LineWidth', 1.4, ... %[output:8dd9c4c7]
    'Color', [0.10, 0.60, 0.30], ... %[output:8dd9c4c7]
    'DisplayName', 'Ordinary - reference'); %[output:8dd9c4c7]

hold on; %[output:8dd9c4c7]

plot(adaptiveTime, adaptiveReferenceError, ... %[output:8dd9c4c7]
    '-', ... %[output:8dd9c4c7]
    'LineWidth', 1.2, ... %[output:8dd9c4c7]
    'Color', [0.55, 0.15, 0.70], ... %[output:8dd9c4c7]
    'DisplayName', 'Adaptive - reference'); %[output:8dd9c4c7]

yline(0.0, ':', 'Color', [0.35, 0.35, 0.35]); %[output:8dd9c4c7]

grid on; %[output:8dd9c4c7]
box on; %[output:8dd9c4c7]
xlabel('Physical time (s)'); %[output:8dd9c4c7]
ylabel('Displacement error'); %[output:8dd9c4c7]
title('Coarse-step discretization error'); %[output:8dd9c4c7]
legend('Location', 'best'); %[output:8dd9c4c7]

% Adaptive versus ordinary at the same outer time step
nexttile; %[output:8dd9c4c7]

plot(adaptiveTime, adaptiveOrdinaryError, ... %[output:8dd9c4c7]
    '-', ... %[output:8dd9c4c7]
    'LineWidth', 1.3, ... %[output:8dd9c4c7]
    'Color', [0.85, 0.20, 0.15]); %[output:8dd9c4c7]

yline(0.0, ':', 'Color', [0.35, 0.35, 0.35]); %[output:8dd9c4c7]

grid on; %[output:8dd9c4c7]
box on; %[output:8dd9c4c7]
xlabel('Physical time (s)'); %[output:8dd9c4c7]
ylabel('Adaptive - ordinary'); %[output:8dd9c4c7]
title(sprintf('Same-dt consistency: max = %.2e', ... %[output:group:2f7a4b42] %[output:8dd9c4c7]
    maxAdaptiveOrdinaryError)); %[output:group:2f7a4b42] %[output:8dd9c4c7]

fprintf('\nAll verification checks passed.\n'); %[output:810e868f]
fprintf('adaptiveAnalyze completed every outer time target.\n'); %[output:445775ca]
fprintf('The adaptive and ordinary dt = 0.02 solutions agree.\n'); %[output:5a808a8d]
fprintf(['Their difference from dt = 0.001 is time-discretization ', ... %[output:group:0d0a7c13] %[output:6dd2399b]
    'error, not an incomplete outer step.\n']); %[output:group:0d0a7c13] %[output:6dd2399b]
ops.wipe();
%%
%[text] ### Local functions
%%
function [time, displacement] = runFixedAnalysis( ...
    ops, p, dt, algorithm, tolerance, maxIterations)
%RUNFIXEDANALYSIS Run an ordinary fixed-step transient analysis.

buildModel(ops, p);
configureAnalysis(ops, algorithm, tolerance, maxIterations);

numberOfSteps = round(p.duration / dt);

time = zeros(numberOfSteps + 1, 1);
displacement = zeros(numberOfSteps + 1, 1);

for i = 1:numberOfSteps
    code = ops.analyze(1, dt);

    if code ~= 0
        error('Analysis failed at step %d, time %.8f, code %d.', ...
            i, ops.getTime(), code);
    end

    time(i + 1) = ops.getTime();
    displacement(i + 1) = ops.nodeDisp(2, 1);
end
end

function buildModel(ops, p)
%BUILDMODEL Create a nonlinear SDOF oscillator.
%
% The excitation amplitude exceeds the Steel02 yield force, producing
% repeated yielding and nonlinear hysteretic response.

ops.wipe();

ops.model('basic', '-ndm', 1, '-ndf', 1);

ops.node(1, 0.0);
ops.node(2, 0.0);

ops.fix(1, 1);
ops.mass(2, p.mass);

ops.uniaxialMaterial( ...
    'Steel02', 1, ...
    p.Fy, p.E0, p.b, ...
    p.R0, p.cR1, p.cR2);

ops.element( ...
    'zeroLength', 1, 1, 2, ...
    '-mat', 1, ...
    '-dir', 1);

% The Trig time series applies:
%
%   forceAmplitude * sin(2*pi*time/forcePeriod)
ops.timeSeries( ...
    'Trig', 1, ...
    0.0, p.duration, p.forcePeriod, ...
    '-factor', p.forceAmplitude);

ops.pattern('Plain', 1, 1);
ops.load(2, 1.0);

% Small mass-proportional damping.
ops.rayleigh(p.massDamping, 0.0, 0.0, 0.0);
end

function configureAnalysis(ops, algorithm, tolerance, maxIterations)
%CONFIGUREANALYSIS Configure average-acceleration Newmark integration.

ops.constraints('Plain');
ops.numberer('Plain');
ops.system('BandGeneral');

ops.test( ...
    'NormDispIncr', ...
    tolerance, ...
    maxIterations, ...
    0);

ops.algorithm(algorithm);
ops.integrator('Newmark', 0.5, 0.25);
ops.analysis('Transient');
end

function deleteFiles(responseFile, logFile)
%DELETEFILES Delete temporary recorder and recovery-log files.

if isfile(responseFile)
    delete(responseFile);
end

if isfile(logFile)
    delete(logFile);
end
end

%[text] ### Interpreting the comparison
%[text] Compare ordinary and adaptive solutions only at the same outer time stations. Recovery statistics describe convergence effort; agreement with the fine reference is the separate measure of time-integration accuracy.

